// Shared helpers for robots.txt / sitemap.xml / rss.xml (API-DD §2: generated by Nuxt from the public API).
// Only public endpoints are read, so drafts, withdrawn and trashed articles can never appear.
import type { H3Event } from 'h3'

export interface FeedArticle {
  slug: string
  title: string
  summary: string
  canonical_path: string
  first_published_at: string
  public_updated_at: string
  category: { name: string } | null
  tags: { name: string }[]
}

interface Page<T> {
  data: T[]
  meta: { page: number, total_pages: number }
}

export function siteUrl(event: H3Event): string {
  return String(useRuntimeConfig(event).public.siteUrl).replace(/\/+$/, '')
}

export function publicApi<T>(event: H3Event, path: string, query?: Record<string, string | number>): Promise<T> {
  const { apiInternalUrl } = useRuntimeConfig(event)
  return $fetch<T>(path, { baseURL: apiInternalUrl, query, timeout: 10_000 })
}

/** Every public article, newest first (paged at the API maximum of 100; bounded for safety). */
export async function allArticles(event: H3Event, limit = 5000): Promise<FeedArticle[]> {
  const out: FeedArticle[] = []
  for (let page = 1; out.length < limit; page++) {
    const res = await publicApi<Page<FeedArticle>>(event, '/api/v1/articles', { page, page_size: 100 })
    out.push(...res.data)
    if (page >= res.meta.total_pages || res.data.length === 0) break
  }
  return out.slice(0, limit)
}

const XML_ESCAPES: Record<string, string> = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', '\'': '&apos;' }

/** Escapes text for XML and drops characters that are illegal in XML 1.0. */
export function xml(text: string): string {
  // eslint-disable-next-line no-control-regex
  return text.replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f￾￿]/g, '').replace(/[&<>"']/g, c => XML_ESCAPES[c]!)
}

/** Absolute URL with every path segment percent-encoded (Chinese slugs are not allowed, but be safe). */
export function absolute(base: string, path: string): string {
  return base + encodeURI(path)
}
